import test from "node:test";
import assert from "node:assert/strict";
import { eligible } from "./eligibility.mjs";
test("eligibility starts at age 18", () => {
  assert.equal(eligible(17), false);
  assert.equal(eligible(18), true);
  assert.equal(eligible(19), true);
});

test("valid ages below the boundary are ineligible", () => {
  for (const age of [0, 1, 10, 16]) {
    assert.equal(eligible(age), false);
  }
});

test("valid ages above the boundary remain eligible", () => {
  for (const age of [20, 65]) {
    assert.equal(eligible(age), true);
  }
});

